<?php
use App\Http\Controllers\Api\V1\Warehouse\Finance\WarehouseFinanceController as C; use App\Http\Middleware\ResolveWarehouseScope; use Illuminate\Support\Facades\Route;
Route::middleware(['api','auth:sanctum',ResolveWarehouseScope::class])->group(function():void{
