 Route::prefix('api/v1/warehouse/finance')->group(function():void{Route::get('/dashboard',[C::class,'dashboard'])->middleware('permission_or_snapshot:warehouse.finance.invoice.view');Route::get('/sales-invoices',[C::class,'invoices'])->middleware('permission_or_snapshot:warehouse.finance.invoice.view');Route::post('/goods-receipts/{grId}/invoice',[C::class,'generate'])->middleware('permission_or_snapshot:warehouse.finance.invoice.create');Route::get('/customer-receipts',[C::class,'receipts'])->middleware('permission_or_snapshot:warehouse.finance.receipt.view');Route::post('/customer-receipts',[C::class,'postReceipt'])->middleware('permission_or_snapshot:warehouse.finance.receipt.create');Route::post('/customer-receipts/{id}/void',[C::class,'voidReceipt'])->middleware('permission_or_snapshot:warehouse.finance.receipt.void');Route::get('/margin',[C::class,'margin'])->middleware('permission_or_snapshot:warehouse.finance.margin.view');});
